const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];let selected=null,cart=[];
function card(a){return `<button class="art-card" data-id="${a.id}" aria-label="View ${a.title} by ${a.artist}"><span class="image-wrap"><img loading="lazy" src="${a.img}" alt="${a.title}, an original ${a.medium.toLowerCase()} artwork by ${a.artist}"></span><span class="art-card-info"><strong>${a.title}</strong><b>$${a.price.toLocaleString()}</b><span>${a.artist}, ${a.year}</span><span>${a.medium}</span></span></button>`}
function render(list=artworks){$('#gallery-grid').innerHTML=list.map(card).join('');$('#result-count').textContent=list.length;bindCards()}function bindCards(){$$('.art-card').forEach(el=>el.onclick=()=>openArtwork(+el.dataset.id))}
$('#featured-grid').innerHTML=artworks.slice(0,3).map(card).join('');render();
function showPage(id){$$('.page').forEach(p=>p.classList.toggle('active',p.id===id));window.scrollTo(0,0);history.replaceState(null,'',`#${id}`)}$$('[data-page]').forEach(b=>b.onclick=e=>{e.preventDefault();showPage(b.dataset.page)});
function openArtwork(id){selected=artworks.find(a=>a.id===id);$('#detail-image').src=selected.img;$('#detail-image').alt=selected.title;$('#detail-artist').textContent=`${selected.artist} · ${selected.year}`;$('#detail-title').textContent=selected.title;$('#detail-meta').textContent=selected.meta;$('#detail-price').textContent=`$${selected.price.toLocaleString()}`;$('#art-dialog').showModal()}bindCards();
$$('.dialog-close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.onclick=e=>{if(e.target===d)d.close()});
function toggleCart(open){$('.cart').classList.toggle('open',open);$('.scrim').classList.toggle('open',open);$('.cart').setAttribute('aria-hidden',!open)}$('.bag-btn').onclick=()=>toggleCart(true);$('.cart-close').onclick=()=>toggleCart(false);$('.scrim').onclick=()=>toggleCart(false);
$('#add-to-bag').onclick=()=>{if(!cart.some(x=>x.id===selected.id))cart.push(selected);updateCart();$('#art-dialog').close();$('.toast').classList.add('show');setTimeout(()=>$('.toast').classList.remove('show'),1800);toggleCart(true)};
function updateCart(){$('.bag-count').textContent=cart.length;$('#checkout-btn').disabled=!cart.length;$('#subtotal').textContent='$'+cart.reduce((s,a)=>s+a.price,0).toLocaleString();$('#cart-items').innerHTML=cart.length?cart.map(a=>`<div class="cart-item"><img src="${a.img}" alt=""><div><h3>${a.title}</h3><p>${a.artist}</p><b>$${a.price.toLocaleString()}</b></div><button data-remove="${a.id}" aria-label="Remove ${a.title}">×</button></div>`).join(''):'<p class="empty-cart">Your bag is waiting for something beautiful.</p>';$$('[data-remove]').forEach(b=>b.onclick=()=>{cart=cart.filter(a=>a.id!=b.dataset.remove);updateCart()})}
$('#checkout-btn').onclick=()=>{toggleCart(false);$('#checkout-dialog').showModal()};$('#checkout-form').onsubmit=e=>{e.preventDefault();e.target.innerHTML='<p class="eyebrow">Step 2 of 2</p><h2>Payment is ready for integration.</h2><p>This polished prototype intentionally stops before processing a real transaction.</p>'};
function filter(){let ar=$('#artist-filter').value,me=$('#medium-filter').value,pr=$('#price-filter').value;render(artworks.filter(a=>(ar==='all'||a.artist===ar)&&(me==='all'||a.medium===me)&&(pr==='all'||(pr==='under'?a.price<2500:a.price>=2500))))}$$('.filters select').forEach(s=>s.onchange=filter);$('#clear-filters').onclick=()=>{$$('.filters select').forEach(s=>s.value='all');filter()};$('.filter-toggle').onclick=e=>{let o=$('.filters').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',o)};
$('.announcement button').onclick=()=>$('.announcement').remove();$('#contact-btn').onclick=()=>location.href='mailto:hello@atelierno8.gallery';$$('.open-artist').forEach(b=>b.onclick=()=>alert('Artist profile opened — biography, available works, and studio notes would appear here.'));if(location.hash&&$(location.hash))showPage(location.hash.slice(1));
